-- Reconstructed application code from output_outlaw_beta (1).lua.
-- Names are inferred from usage; ambiguous values retain temporary names.
-- Includes all 386 original application bodies with ordinary Lua control flow.
-- Startup uses gamesense/websockets, checks dependencies, and initializes once.
-- The injected require override and automatic __newindex execution are removed.
-- Requires the original gamesense/LuaJIT APIs and external modules.
-- Whole execution inside the Windows game client has not been tested.

-- Plain constructor for the remaining indirect table-constructor references.
local function new_table(initial)
    return initial or {}
end

-- Dependencies are checked before touching game interfaces or creating UI.
local function __outlaw_check_dependencies()
    local modules = {
        "ffi", "bit", "vector",
        "gamesense/http", "gamesense/images", "gamesense/msgpack",
        "gamesense/csgo_weapons", "gamesense/antiaim_funcs"
    }
    local failures = {}
    for i = 1, #modules do
        local name = modules[i]
        local ok, result = pcall(require, name)
        if not ok or result == nil or result == false then
            failures[#failures + 1] = {name = name, detail = tostring(result)}
        end
    end
    if #failures == 0 then
        return true
    end

    local log = client and client.error_log or print
    log("[outlaw] Startup stopped: required dependencies could not be loaded.")
    for i = 1, #failures do
        local failure = failures[i]
        log("[outlaw] " .. failure.name .. ": " .. failure.detail)
    end
    log("[outlaw] Enable Allow unsafe scripts for ffi. Install the listed gamesense/*.lua libraries under lua/gamesense/.")
    return false
end

-- The supplied interpreter stops generic iteration on nil or false.
local function truthy_iterator(iterator, state, control)
    return function(current_state, current_control)
        local key, value = iterator(current_state, current_control)
        if key then
            return key, value
        end
    end, state, control
end

